    queues: BTreeMap<QueueName, Queue>,
    clock: Time,
    next_message: MessageId,
    next_handle: ReceiptHandle,
}

impl Default for Broker {
    fn default() -> Self {
        Self {
            queues: BTreeMap::new(),
            clock: Time::START,
            next_message: MessageId::FIRST,
            next_handle: ReceiptHandle::FIRST,
        }
    }
}

/// The result members of a successful command.
#[derive(Debug, Serialize)]
#[serde(untagged)]
enum Success<'a> {
    Done {},
    Now {
        #[serde(rename = "Now")]
        now: Time,
    },
    Queues {
        #[serde(rename = "QueueNames")]
        names: Vec<&'a QueueName>,
    },
    Attributes {
        #[serde(rename = "Attributes")]
        attributes: AttributesView<'a>,
        #[serde(rename = "Counts")]
        counts: Counts,
    },
    Sent {
        #[serde(rename = "MessageId")]
        message_id: MessageId,
        #[serde(rename = "SequenceNumber", skip_serializing_if = "Option::is_none")]
        sequence_number: Option<SequenceNumber>,
    },
    Received {
        #[serde(rename = "Messages")]
        messages: Vec<Delivery>,
    },
}

#[derive(Serialize)]
struct SuccessLine<'a, 'b> {
    ok: bool,
    #[serde(flatten)]
    result: &'b Success<'a>,
}

#[derive(Serialize)]
struct FailureLine<'a> {
    ok: bool,
    error: ErrorBody<'a>,
}

#[derive(Serialize)]
struct ErrorBody<'a> {
    code: ErrorCode,
    message: &'a str,
