    s.tick(299);
    assert_eq!(send(&mut s, "same"), json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    s.tick(1);
    assert_eq!(send(&mut s, "same"), json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
    s.run(json!({"Command": "PurgeQueue", "QueueName": "f.fifo"}));
